export function ProjectsNew() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.projects.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/projects/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New project" actions={<Link to="/projects" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <ProjectsForm
        fields={PROJECTS_CREATE}
        initial={EMPTY_PROJECTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toProjectsCreateInput(values))}
      />
    </Pane>
  );
}

export function ProjectsDetail() {
  const { id: rawId } = useParams({ from: "/projects/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.projects.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["projects"]["update"]) => client.projects.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["projects"]["delete"]) => client.projects.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/projects" });
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.name) || "Project " + text(row.id)}
      actions={
        <>
          <Link to="/projects" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this project?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <ProjectsForm
          fields={PROJECTS_UPDATE}
          initial={projectsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toProjectsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Color">{text(row.color) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Tasks">
          {row.tasks.length === 0 ? (
            "—"
          ) : (
            <ul className="space-y-1">
              {row.tasks.map(item => (
                <li key={text(item.id)}>{text(item.title)}</li>
              ))}
            </ul>
          )}
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}
